#pragma once

/// @file
/// @brief Locales: the compact CLDR subset (LocaleData.cpp, generated by tools/i18n/), and what expressions format
/// with it: plural categories, numbers, percents, currencies, dates and times, relative times, lists, and text
/// compared for sorting.

#include <array>
#include <cstddef>
#include <cstdint>
#include <span>
#include <string>
#include <string_view>

namespace affresco::format::detail {

/// How many currencies the subset has symbols for.
inline constexpr std::size_t currencyCount = 14;
/// How many relative-time units: year, month, week, day, hour, minute, second.
inline constexpr std::size_t relativeUnitCount = 7;

/// A plural category (CLDR's cardinal ones), in CLDR's order.
enum class Plural : std::uint8_t { Zero, One, Two, Few, Many, Other };

/// @brief One unit's relative-time words and patterns.
struct RelativeUnit {
	std::array<std::string_view, 3> words;  ///< "yesterday", "today", "tomorrow" (or "" where CLDR has none).
	std::array<std::string_view, 6> future; ///< "in {0} days", per Plural ("" where the locale doesn't use it).
	std::array<std::string_view, 6> past;   ///< "{0} days ago", per Plural.
};

/// @brief One locale of the CLDR subset.
struct LocaleData {
	std::string_view tag;                                        ///< "en", "ar".
	bool rightToLeft = false;                                    ///< Its writing is right to left.
	std::string_view decimal;                                    ///< The decimal separator.
	std::string_view group;                                      ///< The grouping separator.
	std::string_view percentSign;                                ///< "%", with its marks.
	std::string_view minusSign;                                  ///< "-", with its marks.
	int minimumGroupingDigits = 1;                               ///< 2: "1234" isn't grouped, "12 345" is.
	std::string_view decimalPattern;                             ///< "#,##0.###".
	std::string_view percentPattern;                             ///< "#,##0%".
	std::string_view currencyPattern;                            ///< "¤#,##0.00", ";" before a negative one.
	std::array<std::string_view, 5> plurals;                     ///< The conditions of zero to many ("" if unused).
	std::array<std::string_view, currencyCount> currencySymbols; ///< Per currencyCodes.
	std::array<std::string_view, 12> months;                     ///< "January".
	std::array<std::string_view, 12> shortMonths;                ///< "Jan".
	std::array<std::string_view, 7> days;                        ///< "Sunday" first.
	std::array<std::string_view, 7> shortDays;                   ///< "Sun" first.
	std::string_view am;                                         ///< "AM".
	std::string_view pm;                                         ///< "PM".
	std::array<std::string_view, 4> dateFormats;                 ///< Full, long, medium, short: "EEEE, MMMM d, y".
	std::array<std::string_view, 4> timeFormats;                 ///< Likewise: "h:mm a".
	std::array<std::string_view, 4> dateTimeFormats;             ///< "{1}, {0}": {1} the date, {0} the time.
	std::array<RelativeUnit, relativeUnitCount> relative;        ///< Per unit.
	std::array<std::string_view, 4> andList;                     ///< Start, middle, end, two: "{0}, {1}".
	std::array<std::string_view, 4> orList;                      ///< Likewise, with "or".
};

/// The currencies the subset has symbols for: "USD", "EUR", ...
extern const std::array<std::string_view, currencyCount> currencyCodes;
/// Their usual number of decimals (JPY 0).
extern const std::array<int, currencyCount> currencyDigits;

/// @brief Every locale of the subset.
/// @return Them; constant.
[[nodiscard]] std::span<const LocaleData> localeData() noexcept;

/// @brief Finds the locale data for a tag, by its language: "fr-CA" and "fr_CA.UTF-8" find "fr".
/// @param tag A BCP 47 tag, or a POSIX locale name.
/// @return Its data; English's for a language the subset hasn't.
[[nodiscard]] const LocaleData& findLocale(std::string_view tag) noexcept;

/// @brief Normalizes a tag: "fr_CA.UTF-8" is "fr-CA", "C" and "POSIX" are "en".
/// @param tag A BCP 47 tag, or a POSIX locale name.
/// @return The BCP 47 tag ("" for an empty one).
[[nodiscard]] std::string normalizeTag(std::string_view tag);

/// @brief The plural category of a number in a locale.
/// @param locale The locale.
/// @param number The number.
/// @param decimals Its visible decimals (v): 1 for "1.0", which is "other" in English.
/// @return Its category.
[[nodiscard]] Plural pluralCategory(const LocaleData& locale, double number, int decimals = 0) noexcept;

/// @brief A plural category by its name.
/// @param name "zero", "one", "two", "few", "many" or "other".
/// @param category Set to it.
/// @return Whether the name is one.
[[nodiscard]] bool pluralFromName(std::string_view name, Plural& category) noexcept;

/// @brief Formats a number in a locale: separators, grouping, the locale's minus sign.
/// @param locale The locale.
/// @param number The number.
/// @param fewest Fewest decimals.
/// @param most Most decimals (rounded half away from zero).
/// @return The text: "1,234.5" in English, "1.234,5" in Italian.
[[nodiscard]] std::string formatNumber(const LocaleData& locale, double number, int fewest = 0, int most = 3);

/// @brief Formats a ratio as a percent: 0.25 is "25%" ("25 %" in French).
/// @param locale The locale.
/// @param ratio The ratio.
/// @param decimals Its decimals.
/// @return The text.
[[nodiscard]] std::string formatPercent(const LocaleData& locale, double ratio, int decimals = 0);

/// @brief Formats an amount of money with its currency's symbol and decimals.
/// @param locale The locale.
/// @param amount The amount.
/// @param code "EUR"; a code the subset hasn't is written as is, with 2 decimals.
/// @return The text: "€1,234.50" in English, "1.234,50 €" in Italian.
[[nodiscard]] std::string formatCurrency(const LocaleData& locale, double amount, std::string_view code);

/// @brief Formats a time with a CLDR pattern (y M L d E a h H k K m s z, text between quotes).
/// @param locale The locale (names of months and days, AM and PM).
/// @param milliseconds Since 1970, UTC.
/// @param pattern The pattern, or a style: "full", "long", "medium", "short" (the date's).
/// @param universal In UTC rather than the computer's time zone.
/// @return The text.
[[nodiscard]] std::string formatDate(const LocaleData& locale, double milliseconds, std::string_view pattern,
                                     bool universal);

/// @brief Formats a time of day by a style.
/// @param locale The locale.
/// @param milliseconds Since 1970, UTC.
/// @param style "full", "long", "medium", "short", or a CLDR pattern.
/// @param universal In UTC rather than the computer's time zone.
/// @return The text: "3:05 PM" in English, "15:05" in Italian.
[[nodiscard]] std::string formatTime(const LocaleData& locale, double milliseconds, std::string_view style,
                                     bool universal);

/// @brief Formats a relative time: -1 "day" is "yesterday", 3 "hour" is "in 3 hours".
/// @param locale The locale.
/// @param value How many units, negative in the past.
/// @param unit "year", "month", "week", "day", "hour", "minute" or "second" (a final "s" is allowed).
/// @param text Set to the text.
/// @return Whether the unit is one of them.
[[nodiscard]] bool formatRelative(const LocaleData& locale, double value, std::string_view unit, std::string& text);

/// @brief Joins items as a list: "a, b and c", or with "or".
/// @param locale The locale.
/// @param items The items, as text.
/// @param disjunction "or" rather than "and".
/// @return The text.
[[nodiscard]] std::string formatList(const LocaleData& locale, std::span<const std::string> items, bool disjunction);

/// @brief Compares text for sorting: letters first without accents or case, then accents, then case.
/// @param a A text.
/// @param b Another.
/// @return Negative, zero or positive.
[[nodiscard]] int compareText(std::string_view a, std::string_view b) noexcept;

} // namespace affresco::format::detail
